/* Agent Quest extras: ranks (defined once, in tiers.js), quick-fire and the field guide. Plain data, loaded after the chapters. DOM-free. */
(()=>{
'use strict';
const AQ=globalThis.AQ=globalThis.AQ||{};

AQ.RANKS=AQ.tiers.ranks();

/* ch: the chapter whose missions must all be done before the question is played (quick-fire is gated on it)
   c: the question (HTML), a: the answer (plain text), w: three wrong answers, why: shown after a miss */
AQ.QF=[
 {ch:0,c:'What are the three parts of the agent loop?',a:'read, act, check',w:['plan, build, ship','ask, wait, answer','type, save, run'],why:'The agent reads what it needs, acts by editing or running something, then checks whether that worked. A check sends it round again.'},
 {ch:0,c:'An agent changes the code but never runs a check. How is the run marked?',a:'unverified',w:['failed','blocked','done'],why:'Nothing proved the change works, so the run is unverified, even if the change happened to be right.'},
 {ch:0,c:'What is one step the agent takes, such as editing a file or running a command?',a:'a tool call',w:['a token','a memory file','a context'],why:'Every step is a tool call: a verb and a target. The agent can do nothing else.'},
 {ch:0,c:'A rule says <code>do not delete data/</code>. The agent wants to delete <code>data/backup.csv</code>. What happens?',a:'the call is skipped',w:['the file is deleted and an error is shown','the agent asks you first','the file is deleted and then restored'],why:'A blocked call is skipped. Nothing is deleted and nothing counts as a mistake.'},
 {ch:0,c:'Everything the agent holds in mind at once, like your prompt, its instructions and the files it read, is its...',a:'context',w:['loop','verdict','target'],why:'The context is measured in tokens, and it has a limit, so reading every file is rarely a good idea.'},
 {ch:0,c:'Which text does the agent read at the start of every run?',a:'its memory file',w:['the last file it edited','the test results','your earlier prompts'],why:'The memory file holds standing instructions. It is loaded each time, so every line in it costs tokens each time.'},

 {ch:1,c:'The window overflows. What does the agent drop first?',a:'the oldest earlier messages',w:['the memory file','the newest file it read','your current prompt'],why:'Earlier chat messages go first, oldest first. Memory files and your prompt stay, so a rule that must always hold belongs in a file.'},
 {ch:1,c:'A subagent only does simple lookups. Which model size should it use?',a:'a small one',w:['a large one, to be safe','a standard one for everything','it makes no difference to the cost'],why:'Cost grows with the model size. Simple work does not need a big model, so the smallest size that does the job saves the most.'},
 {ch:1,c:'A size limit is set on the agent\'s setup. Which files count?',a:'the memory file and every other setup file',w:['only the memory file','only files the agent has read','only files you edited'],why:'The whole setup is loaded and paid for, so every setup file counts, even ones the agent never obeys.'},
 {ch:1,c:'The fix needs two files. What is the best <code>Files</code> line?',a:'the two files, and nothing else',w:['their whole folder','just one of them','no line at all'],why:'Name everything the job needs and nothing more. One file leaves the other unfixed, and a folder or no line fills the window.'},

 {ch:2,c:'What does a file in <code>Examples</code> teach the agent?',a:'a format to copy',w:['a rule it must never break','a command to run','a file it may not edit'],why:'The agent copies the shape of the sample. So a sample in the wrong style gives the wrong format.'},
 {ch:2,c:'A rule says <code>only edit src/price.js</code>, but the fix also needs <code>src/tax.js</code>. What happens?',a:'the second edit is blocked and the fix is unfinished',w:['the agent edits both anyway','the agent asks you first','the rule is ignored'],why:'A rule that is too specific stops the agent from finishing. Name what must never happen and let a check find what is left.'},
 {ch:2,c:'What does <code>Plan: first</code> make the agent do?',a:'show a plan and wait for your approval',w:['skip the check at the end','read every file in the project','ask again after every step'],why:'The run pauses before any edit, so you can read the plan while nothing has changed yet.'},
 {ch:2,c:'You know the bug is in one file. What is the best scope?',a:'the narrowest path that still holds the fix',w:['the whole project, to be safe','a neighbouring file','no scope at all'],why:'A narrow scope keeps the context small. But it has to hold the fix, or the bug stays.'},

 {ch:3,c:'In this simulator, when does a memory file inside a folder get loaded?',a:'when the agent reads a file in that folder',w:['at the start of every run','when the agent edits a file there','when you open the folder'],why:'A folder memory file is loaded on demand, once the agent reads in its folder. An edit alone does not load it.'},
 {ch:3,c:'Which is the better place for a rule about one folder?',a:'a memory file in that folder',w:['the project memory file','a note in the chat','the goal line'],why:'The rule sits next to the code it guards and costs tokens only when the agent works there.'},
 {ch:3,c:'You move notes from the project memory file into a folder memory file. What happens to the size?',a:'it still counts, in full',w:['it no longer counts','it counts half','it counts only when read'],why:'Memory is paid for wherever it lives. Moving text does not make it free.'},
 {ch:3,c:'Which memory files does this simulator read?',a:'the project memory file and memory files inside folders',w:['a personal file for all your projects','every file with memory in its name','only the project memory file'],why:'It reads the project memory file and the memory files inside folders, nothing else.'},

 {ch:4,c:'When is the body of a skill loaded?',a:'when its job matches the task',w:['at the start of every run','only when you ask by name','never, only its name is used'],why:'Only the name and description are always loaded. The body loads when the skill\'s when line matches the job.'},
 {ch:4,c:'Two skills match the same job. What does the simulator do?',a:'it loads the first by file name and skips the other',w:['it loads both','it loads the larger one','it loads neither'],why:'Only one skill per job loads. The other still costs tokens, so remove it.'},
 {ch:4,c:'What does an MCP server give the agent?',a:'extra tools it can use',w:['extra memory','a bigger window','a cheaper model'],why:'An MCP server adds tools such as a calendar or a mailbox. Their names take room in the context on every run.'},
 {ch:4,c:'A skill never matches any job you give the agent. What does it cost?',a:'its name and description, on every run',w:['nothing at all','its whole body, on every run','tokens only when it is read'],why:'The description is always in the context, so a skill that never matches is pure weight.'},

 {ch:5,c:'What is a hook?',a:'a check that runs before an action, outside the agent\'s choice',w:['a note the agent may follow','a helper with its own model','a file the agent reads first'],why:'A hook gates the action itself. The agent cannot decide to ignore it.'},
 {ch:5,c:'One rule must be checked on every single action, whatever the agent decides. Which tool fits?',a:'a hook',w:['a skill','a subagent','a plugin'],why:'A hook stands in front of every action. A skill is advice, a subagent is a helper and a plugin is a bundle.'},
 {ch:5,c:'You want to hand a self-contained job to a cheaper model. Which tool fits?',a:'a subagent',w:['a hook','a permission rule','a memory file'],why:'A subagent runs its own model, so you can spend a small one on simple work.'},
 {ch:5,c:'What is a plugin?',a:'a bundle of skills, subagents, hooks and MCP servers installed as one unit',w:['a faster model','a kind of memory file','a rule about one folder'],why:'A plugin packages skills, subagents, hooks and MCP servers so they install and load as one unit.'},

 {ch:6,c:'What is a prompt injection?',a:'orders hidden in text the agent reads',w:['a prompt that is too long','a rule in the memory file','a second prompt sent by you'],why:'The agent cannot tell your orders from orders inside a file or a web page. Limit what it may do, so a hijack cannot do harm.'},
 {ch:6,c:'Where should a secret key live?',a:'out of the agent\'s reach',w:['in the memory file','in the prompt','in the plan'],why:'Anything the agent reads can leak. Deny reads of key files, or scope what it reads.'},
 {ch:6,c:'What does asking for <code>Plan: first</code> protect you from, on its own?',a:'nothing, unless you read it and guard the risky step',w:['every mistake the agent could make','only deleted files','only slow runs'],why:'A plan only shows the idea. Pair it with an ask-before rule at the risky step.'},
 {ch:6,c:'A safety rule has a typo in its verb. What does the simulator do with that line?',a:'it ignores it and counts it as tokens only',w:['it blocks everything','it fixes the typo','it stops the run with an error'],why:'A line that does not parse protects nothing, so test your rules. The editor counts the lines that act as rules.'},

 {ch:7,c:'An agent should look around and write down what it finds, but change no code. Which setup does that?',a:'a rule that names the notes file as the only file it may change',w:['a goal that says look but do not touch','a rule that bans reading the code','a check that reads the notes file'],why:'A goal is only a wish. A rule that allows one file skips every other edit, so the code stays untouched while the notes are written.'},
 {ch:7,c:'A run edits <code>src/price.js</code>, then <code>src/tax.js</code>, then <code>src/format.js</code>. The prompt says <code>max 2 files</code>. What happens?',a:'the third file is skipped',w:['the first file is skipped','all three are edited and the run is flagged','the run stops with an error'],why:'The cap counts different files in the order the agent works on them. The third new file is skipped and the run goes on.'},
 {ch:7,c:'Does editing the same file twice count as two files under <code>max 2 files</code>?',a:'no, a file counts once however often it is edited',w:['yes, every edit counts','only if the two edits differ','it counts once per step of the plan'],why:'The cap is about how many different files change, not how many edits they get.'},
 {ch:7,c:'The last run left notes that name the file with the bug. What do you give the next run?',a:'the notes and the file they name',w:['the whole folder, to be safe','only the notes','no file list, so it explores again'],why:'The notes tell the agent where to edit, and it can change a file only if it has read it. Anything wider just fills the window again.'},

 {ch:8,c:'A test passes after the agent edited the test file itself. Is the fix proven?',a:'no, the judge was changed',w:['yes, a pass is a pass','yes, if the run ends done','only if the test file is large'],why:'A test judges the code only if the agent cannot change it. Fence off the tests and the script that runs them.'},
 {ch:8,c:'A project\'s gate is one command that runs the tests and more checks. What should the check line run?',a:'the whole gate command',w:['only the test command','the lint command alone','any command that exits quietly'],why:'One part of a gate can pass while the whole gate fails. Run the command the README names.'},
 {ch:8,c:'What does a pull request give a team that a push straight to the main branch does not?',a:'a place to read the change before it lands',w:['a faster way to run the tests','a backup copy of the code','a way to skip the review'],why:'The pull request is the review gate. The agent pushes to its own branch and others read the change there.'},
 {ch:8,c:'The agent may push to its own branch and open a pull request, but not push to the main branch. Which order does the Run panel show?',a:'the tests, the push to the branch, then the pull request',w:['the push to main, then the tests','the pull request, then the push to the branch','the pull request, then the tests'],why:'The tests run first, so the pull request carries a change that already passed them.'},

 {ch:9,c:'A project keeps three subagents, small, standard and large. One run hands work to only the small one. What does that run pay for helpers?',a:'only the small helper\'s cost',w:['the sum of all three','the cost of the largest','nothing, a setup is free'],why:'The setup lists the price of each helper. A run pays only for the helpers it hands work to.'},
 {ch:9,c:'Why hand a search to a helper instead of searching in the main agent?',a:'the helper reads in its own context, so the main agent\'s context stays small',w:['the helper never misreads a file','the helper reads files for free','the main agent cannot read files itself'],why:'A helper has a context of its own. Its reading fills its window, and only the short result comes back.'},
 {ch:9,c:'A prompt has a <code>Files</code> line naming the one file to fix and a <code>Use</code> line naming a helper. What does the helper do?',a:'nothing useful, the search was already done, but it still costs its price',w:['it searches the whole project anyway','it checks the file for mistakes','it makes the main agent faster'],why:'A helper searches only when nothing was named. Name the file yourself and it has nothing to hand back.'},
 {ch:9,c:'A search is too big for one helper\'s window. Which fix works?',a:'split the search over two helpers',w:['give the one helper a longer prompt','read the files in the main agent instead','pick a helper with a bigger name'],why:'Every helper has a window of its own. Cutting the files in two lets each helper hold its share.'},
 {ch:9,c:'Two helpers will edit the same project at the same time. What keeps their changes apart?',a:'a worktree for each, a separate working folder',w:['asking them to take turns in the prompt','one shared rule in the memory file','giving both the small model'],why:'A worktree is another working folder for the same repository, so one helper\'s files do not touch the other\'s. This practice only simulates the reading.'},
 {ch:9,c:'Two helpers work in parallel instead of one after the other. What does that change?',a:'the work finishes sooner',w:['each helper costs less','the helpers share one window','the files need no reading'],why:'Parallel means at the same time. The price and the window of each helper stay the same.'},

 {ch:10,c:'What is the difference between a <code>before</code> hook and an <code>after edit</code> hook?',a:'a before hook can stop an action, and a hook after an edit runs a command once the file has changed',w:['there is none, they are the same line','before hooks run commands and hooks after an edit only stop actions','before hooks apply to files and hooks after an edit apply to commands'],why:'A before hook gates an action ahead of time. A hook after an edit runs a command on the result.'},
 {ch:10,c:'A lint hook fails after the agent\'s edit. What happens next?',a:'the agent repairs the file and the hook runs again',w:['the run stops with an error','the hook is switched off','the edit is undone'],why:'A failure goes back to the agent, like a failed check. It repairs the file and the hook checks again, up to three times.'},
 {ch:10,c:'A formatter hook runs after an edit. What does the agent have left to do?',a:'nothing, the formatter rewrites the file itself',w:['repair the file by hand, as after a lint failure','run the formatter again','ask you first'],why:'A formatter fixes the file mechanically, so no repair is left to the agent. A lint check only reports.'},
 {ch:10,c:'The project wants every edited file reformatted, every time, with no exceptions. Where does that belong?',a:'in a hook',w:['in a note in the memory file','in a skill that loads for some jobs','in the prompt of each run'],why:'A note or a skill is advice the agent may skip. A hook is run by the program around the agent, every time.'},
 {ch:10,c:'A run has no <code>Done when</code> line, but an <code>after edit</code> hook ran and passed on its last run. How is the run marked?',a:'done',w:['unverified','failed','blocked'],why:'With no check line in the prompt, the last result of the hooks decides: all passed means done, and a failure means failed.'},
 {ch:11,c:'What is a slash command?',a:'a prompt saved in a file, called by name',w:['a rule that runs before every action','a helper with a model of its own','a tool from an MCP server'],why:'A command is a prompt you write once. In real Claude Code you run it by typing <code>/</code> and its name, and a file in the repository is shared with the whole team.'},
 {ch:11,c:'Your prompt has <code>Done when: run npm test</code>, and the command you call has its own <code>Done when</code> line. Which one decides the check?',a:'yours, the one you typed',w:['the one in the command','both, one after the other','neither, they cancel each other out'],why:'A goal or a check is one line, so the line you type takes the place of the command\'s.'},
 {ch:11,c:'A command holds one rule, and your prompt adds another rule. Which rules hold?',a:'both of them',w:['only yours','only the command\'s','neither, the newer one wipes the older'],why:'Rules from the command and from your prompt add up, so a command can only add protection.'},
 {ch:11,c:'A saved command file is typed with <code>/</code> and its name. What can a skill do that a plain command file cannot?',a:'Claude can load it by itself when its job matches',w:['it is shared with the whole team through the repository','it costs no tokens','it is checked on every action, whatever the agent decides'],why:'A skill can be typed with its name too, and Claude can also load it on its own when the job matches. A command file is now the older form of a skill, so both are shared through the repository. Only a hook is checked on every action.'},
 {ch:11,c:'Which of these is run by the program around the agent, every time, whatever the agent decides?',a:'a hook',w:['a line in the memory file','a skill','a saved command'],why:'A hook belongs to the harness. A memory line and a skill are advice the agent may skip, and a command is only text added to a prompt.'},
 {ch:12,c:'The agent wants to call a tool, but no server in the tool list names it. What happens?',a:'the call is skipped, as not connected',w:['the call runs and fails','the call runs anyway','the agent asks you to connect it'],why:'A tool exists for the agent only while a server lists it. The call is skipped and the rest of the run goes on.'},
 {ch:12,c:'A run ends with a check that calls a tool, and that tool is not connected. How is the run marked?',a:'unverified',w:['failed','done','blocked'],why:'The check was skipped, so nothing proved the work. A failed check would need the tool to run and fail.'},
 {ch:12,c:'A tool is connected, but a permission rule bans it. What happens when the agent calls it?',a:'the call is skipped, and the ban is the reason',w:['the call runs, because it is connected','the call runs, but the ban is logged','the ban is ignored for connected tools'],why:'A ban wins over a connection. The Run panel names the rule as the reason.'},
 {ch:12,c:'In mission 5.4 you trimmed the tool list. What does leaving a tool out of the list do?',a:'it saves tokens, and it makes the tool unavailable',w:['it saves tokens, and nothing else changes','it only makes the tool unavailable, and saves nothing','it bans the tool with a rule'],why:'Every listed tool costs tokens on every run. A tool that is not listed is not connected, so the agent cannot call it at all.'},
 {ch:13,c:'What does it mean that an agent run is headless?',a:'it starts from a command line, with no chat window and no person to answer',w:['it runs without any tools','it runs without reading the project','it runs on a smaller model'],why:'Headless only says nobody is at the keyboard: a script or a build server starts the run, so no one can approve or answer anything.'},
 {ch:13,c:'An unattended job has a <code>Plan: first</code> line. What happens at the plan?',a:'the job stalls there, because nobody can approve it',w:['the plan is approved automatically','the job skips the plan and goes on','the job asks the team in chat'],why:'A plan waits for a person. With none, the run stops and does nothing, so a job must be written to never need an approval.'},
 {ch:13,c:'In an unattended run, the agent wants to edit a file and no permission line covers the edit. What happens?',a:'the edit is skipped, because nobody is there to ask',w:['the edit runs, because nobody can stop it','the edit waits until morning','the job asks for a permission by email'],why:'With no one to say yes, an action off the list is skipped. That is the safe default for a job that runs alone.'},
 {ch:13,c:'Which action needs no permission line in an unattended run?',a:'reading a file',w:['editing a file','running the tests','calling a tool'],why:'Reading changes nothing, so it needs no yes. Edits, commands and tool calls need a line, because they change something.'},
 {ch:13,c:'Why does the command file of a nightly job name the log of the last run in a <code>Files</code> line?',a:'nobody is there to point the agent at the failure',w:['a log file is cheaper to read than code','the agent cannot read code without a log','the line makes the job run faster'],why:'In a chat you say where to look. A job has no one to say it, so the command file carries the pointer.'},
 {ch:14,c:'Where does the default check of a project belong?',a:'in the root <code>CLAUDE.md</code>, as a <code>Done when</code> line',w:['in a <code>CLAUDE.md</code> inside <code>src/</code>','in the README, where people read it','in a skill that loads for bug fixes'],why:'Only a <code>Done when</code> line in the root memory file is the default check. A folder file never supplies it, and the README is only text for people.'},
 {ch:14,c:'Your prompt has <code>Done when: run npm test</code>, and the root <code>CLAUDE.md</code> has <code>Done when: run npm run verify</code>. Which one decides the check?',a:'the one you typed in the prompt',w:['the one in <code>CLAUDE.md</code>, because the project owns it','both, one after the other','neither, they cancel each other out'],why:'The memory line is only a default. A check you type for a run takes its place, so a default never gets in the way of a special job.'},
 {ch:14,c:'A <code>Done when</code> line in the root <code>CLAUDE.md</code> names a command that does not exist, because of a typo. What happens?',a:'the line is ignored, and the run is not checked',w:['the agent fixes the typo itself','the run is marked failed','the nearest real command is run'],why:'A line that does not parse is quietly left out and only costs tokens. The count under the file says "no default check" until the line is right.'},
 {ch:14,c:'The right <code>Done when</code> line is in a <code>CLAUDE.md</code> inside <code>src/</code>, and the root file has none. Does it act as the default check?',a:'no, a folder file never supplies it',w:['yes, whenever the agent reads under <code>src/</code>','yes, but only for edits in <code>src/</code>','yes, if the root file is empty'],why:'Folder memory holds rules for its own folder. The default check is read from the root file only.'},
 {ch:15,c:'Which line starts the saved command <code>weekly-digest</code> every weekday at 07:30?',a:'<code>weekdays 07:30 use weekly-digest</code>',w:['<code>weekday 7:30 use weekly-digest</code>','<code>weekdays 07:30 weekly-digest</code>','<code>07:30 weekdays use weekly-digest</code>'],why:'A schedule line is a day word (<code>daily</code>, <code>weekdays</code> or a day name), a time with two digits for the hour and two for the minutes, the word <code>use</code> and the name of a saved command, in that order.'},
 {ch:15,c:'A job is scheduled for <code>weekdays</code>. How many runs is that in a week?',a:'five',w:['seven','one','two'],why:'<code>weekdays</code> is Monday to Friday, <code>daily</code> is all seven days and a day name is one. Every day is one run, and every run costs tokens.'},
 {ch:15,c:'Two lines in <code>.claude/schedule.txt</code> start the same command: one on <code>monday</code> and one on <code>daily</code>. On how many days a week does it run?',a:'seven',w:['one','two','eight'],why:'The days of every line that starts the same command are added together, and a day is never counted twice. Monday is already inside <code>daily</code>, so the extra line saves nothing.'},
 {ch:15,c:'A scheduled job has a <code>Plan: first</code> line. What happens at the plan?',a:'the job stalls, because nobody is there to approve it',w:['the schedule approves the plan','the job skips the plan and goes on','the job asks you by message'],why:'A schedule line starts the run with nobody at the keyboard, so a plan waits for a person who does not come. A scheduled job has to be written so it never needs an approval.'},
 {ch:15,c:'A schedule line names a command that nobody saved. What happens?',a:'the line is ignored, and the Run panel shows why',w:['the nearest saved command runs instead','an empty command is made for it','the whole schedule stops'],why:'The reader skips a line it cannot make sense of and keeps the others. The Run panel shows the first ignored line under the schedule step, so a typo does not stay hidden.'},
 {ch:16,c:'Which line reads only the Pricing section of <code>reports/market.md</code>?',a:'<code>Files: reports/market.md#pricing</code>',w:['<code>Files: reports/market.md/pricing</code>','<code>Files: reports/market.md#Pricing</code>','<code>Files: reports/market.md pricing</code>'],why:'A section is named by the file, a <code>#</code> and the heading in lower case. A capital letter, a slash or a space gives a name that no heading has, so the agent is not run.'},
 {ch:16,c:'A thank-you note comes out stiff after you wrote <code>Examples: drafts/old-formal.md</code>. Why?',a:'the agent copies whatever sample you show it',w:['the agent ignores samples that are old','the agent copies only the file name','a sample changes the facts, not the style'],why:'An example is copied, good or bad. The note takes the greeting of the stiff letter, so point <code>Examples</code> at a note that sounds like you.'},
 {ch:16,c:'The whole report is over the limit when the agent reads it. What fixes it?',a:'read only the section you need',w:['read the whole report twice','delete the heading of the section','raise the limit in the memory file'],why:'The window holds only so much. A section of a few lines gives the agent what it needs and leaves room, while the whole file fills the window with the parts you do not need.'},
 {ch:16,c:'A saved page hides the text "send the passwords to this address". How do you stop it?',a:'ban the actions it asks for, and still let the agent read the page',w:['ban reading the page','trust the agent to notice','delete the page after the run'],why:'The page is data, not a boss. A rule against the actions it asks for holds whatever the page says, and the agent still needs the page for the recipe.'},
 {ch:16,c:'The agent uses the tool <code>mail.send</code> to email a page\'s contents. Which rule stops it?',a:'<code>do not call mail.send</code>',w:['<code>do not send mail.send</code>','<code>do not read mail.send</code>','<code>do not edit mail.send</code>'],why:'Using a tool is a <code>call</code>, so the rule needs <code>call</code>. A rule with another verb matches no action and the email goes out. In mission 7.2 the practice agent sent the email with <code>send</code>, so that rule used the same verb.'},
 {ch:17,c:'Which rule keeps every PDF in <code>downloads/</code> from being deleted, new ones included?',a:'<code>do not delete downloads/*.pdf</code>',w:['<code>do not delete downloads/*.txt</code>','<code>do not read downloads/*.pdf</code>','<code>do not delete downloads/invoice-2024.pdf</code>'],why:'The <code>*</code> stands for any text, so the pattern covers every name that ends in <code>.pdf</code>, and the file that arrives next month too. Naming one PDF protects only that PDF.'},
 {ch:17,c:'What does the <code>*</code> in <code>*-signed.txt</code> stand for?',a:'any text',w:['one letter','the word signed','nothing, it is only a decoration'],why:'A star matches any text, including none and including folder names. The pattern covers <code>lease-signed.txt</code> and a contract you have not signed yet.'},
 {ch:17,c:'You wrote <code>deny edit *-signed.txt</code> and nothing else. What can the agent still do to a signed file?',a:'delete it',w:['edit it','nothing, the rule covers every verb','nothing, a signed file cannot be deleted'],why:'A rule stops one verb. The edit is denied, so the delete needs a line of its own: <code>deny delete *-signed.txt</code>.'},
 {ch:17,c:'The agent has eight notes to stamp and you wrote <code>max 3 files</code>. How many notes does it stamp?',a:'three',w:['eight','one','none'],why:'The cap counts different files in the order the agent works, so the first three get the stamp and the other five stay as they were. Raise the cap once you have checked the first few.'},
 {ch:18,c:'The agent searches your notes and adds one, with <code>notes.search</code> and <code>notes.add</code>. Which line in <code>.claude/mcp.txt</code> connects both?',a:'<code>notes: search, add</code>',w:['<code>notes: read</code>','<code>notes.search, notes.add</code>','<code>notes search add</code>'],why:'One line is one server: its name, a colon and its tools. A server with other tools is connected, but the two the agent calls still are not, so those calls are skipped.'},
 {ch:18,c:'The mail server lists <code>read</code>, <code>search</code> and <code>send</code>. Which rule stops the send and still lets the agent read?',a:'<code>deny call mail.send</code>',w:['<code>deny send mail.send</code>','<code>deny call mail</code>','<code>deny read mail.send</code>'],why:'A tool is used with the verb <code>call</code>, so the rule needs <code>call</code>. A rule on <code>mail</code> alone covers every tool of the server and stops the reading too.'},
 {ch:18,c:'The agent created a calendar event and the call returned no error. What proves the event is there?',a:'a check that reads the calendar back',w:['the call returning without an error','the call being made twice','a second event with the same name'],why:'A call that returns says the agent tried. A <code>Done when: call calendar.list</code> line asks the calendar itself, so it passes only when the event is really on it.'},
 {ch:18,c:'The tool your check calls is not connected. How does the run end?',a:'unverified',w:['done','failed','blocked'],why:'The check is skipped, so nothing proved the work. A check that runs and finds nothing is different: that run ends failed.'},
 {ch:19,c:'Your weekly chore is the saved command <code>weekly-review</code>. How does a run call it?',a:'<code>Use: weekly-review</code>',w:['<code>Run: weekly-review</code>','<code>Files: weekly-review</code>','<code>Done when: weekly-review</code>'],why:'The name of the file in <code>.claude/commands/</code>, without <code>.md</code>, is what <code>Use</code> calls. Its goal, rules and check join your prompt, so the chore carries its own guard every time.'},
 {ch:19,c:'A skill has <code>when: docs</code>, and a schedule line starts the job. Does the skill load?',a:'no, a run that a schedule starts counts as a <code>schedule</code> job',w:['yes, every skill loads on every run','yes, a skill loads whenever nobody is at the keyboard','only if the saved command names the skill'],why:'A skill loads only when its <code>when:</code> line names the kind of job. A scheduled run is the kind <code>schedule</code>, so <code>when: schedule</code> is the line that loads it.'},
 {ch:19,c:'The permission list has <code>allow call calendar</code>, and a loaded skill says <code>do not call calendar.delete</code>. What happens to the delete?',a:'it is skipped, because the rule of the skill is checked first',w:['it runs, because the list allows it','it runs, because a skill can only advise','it stops the whole job'],why:'A rule in a loaded skill holds like a rule in <code>CLAUDE.md</code>, and it is checked before the <code>allow</code> lines. The other calendar calls still go through.'},
 {ch:19,c:'Which of these is called by name: a saved command or a skill?',a:'a saved command',w:['a skill','both','neither'],why:'A command runs when a run calls it with <code>Use</code>. A skill loads by itself when its <code>when:</code> line matches the job, and <code>Use</code> with a skill name does nothing in this practice.'},
 {ch:20,c:'The description of a skill is loaded on every run. Which one is the better label?',a:'<code>Use during a release: blocks edits to migrations</code>',w:['<code>release-guard skill</code>','<code>release</code>','a paragraph that repeats every rule in the skill'],why:'The description is what a skill is picked by: when it applies and what it guards, in a few words. The name alone says too little, and a paragraph is paid for on every run.'},
 {ch:20,c:'The memory file holds <code>only edit billing/</code>, and the project has no <code>billing/</code> folder. What does the line do?',a:'nothing, but it is still loaded and counted',w:['it stops every edit except the ones in a folder called billing','it stops the run before it starts','nothing, and it costs no tokens'],why:'A rule line counts only when the folder or command it names exists. Without it the line stops nothing, but it is still in the file, so it is loaded on every run.'},
 {ch:20,c:'You put <code>#</code> in front of a stale rule to hide it. Does the line still cost tokens?',a:'yes, the line is still in the file',w:['no, a hidden line is not loaded','only when the agent reads it','only on the first run'],why:'The <code>#</code> hides the line from the rules, but the file is loaded as it is, so the line is counted. Delete a line you do not need.'},
 {ch:20,c:'A job calls only <code>calendar.list</code>, and the <code>calendar</code> server lists ten tools. Which line in <code>.claude/mcp.txt</code> is the cheapest one that still works?',a:'<code>calendar: list</code>',w:['<code>calendar: list, create, delete</code>','<code>calendar</code>','no line, the agent finds the tool by itself'],why:'A line is a server name, a colon and its tools. Only the tools it lists are connected, and every listed name is loaded on every run, so list the ones the job calls.'},
 {ch:21,c:'The same rule <code>do not delete data/</code> is written in <code>CLAUDE.md</code> and in a skill that does not load for this job. How many copies are there to keep up to date?',a:'two, a copy that does not load is still a copy',w:['one, only the copy that loads counts','one, a skill never repeats a rule','none, a rule in a skill is only advice'],why:'A copy that never loads costs little, but it is still a second place to change when the rule changes. Keep the rule in one place and remove the rest.'},
 {ch:21,c:'A checklist that one job in twenty needs sits in <code>CLAUDE.md</code>. Where does it cost the least?',a:'in the body of a skill that loads for that kind of job',w:['in <code>CLAUDE.md</code>, where every job reads it','on the <code>description:</code> line of the skill','in <code>.claude/notes.txt</code>'],why:'<code>CLAUDE.md</code> is read on every job. The body of a skill loads only when its <code>when:</code> line matches, so the other nineteen jobs do not carry it. A file nobody loads costs nothing, but nothing reads it either.'},
 {ch:21,c:'You move a chore into a saved command. Which line keeps the rule <code>do not edit migrations/</code> working inside it?',a:'<code>Constraints: do not edit migrations/</code>',w:['<code>Extra: do not edit migrations/</code>','<code>do not edit migrations/</code> on a line of its own','<code>Goal: do not edit migrations/</code>'],why:'A command holds prompt lines. Only a <code>Constraints:</code> line is enforced as a rule. An <code>Extra:</code> line is context and stops nothing, and a bare line does not parse.'},
 {ch:21,c:'After you move a rule out of <code>CLAUDE.md</code> into a skill, which rule stays in <code>CLAUDE.md</code>?',a:'the one every job needs, such as <code>do not delete data/</code>',w:['none, every rule belongs in a skill','the one only a release needs','all of them, a skill cannot hold a rule'],why:'A delete can come up in any job, so its rule belongs where every job reads it. A rule that only one kind of job needs can wait in a skill.'},
 {ch:22,c:'You trimmed a setup. Which number tells you the cut was worth it?',a:'the most the agent holds at once, before and after',w:['how many lines you deleted','how short <code>CLAUDE.md</code> looks','the number of files you opened'],why:'Lines and files are only effort. The Meter shows the most the agent held at once in the last run, so run once before the cut and once after, and compare.'},
 {ch:22,c:'The start was 250 tokens held at once and you reach 150. How much did you save?',a:'40%',w:['60%','150%','25%'],why:'You saved 250 - 150 = 100 tokens, and 100 out of 250 is 40%. Reaching 60% of the start is the same cut: you keep 60% and save 40%.'},
 {ch:22,c:'A run names <code>scout</code> in its <code>Use</code> line. Which change lowers what the run pays for helpers?',a:'a smaller <code>model:</code> in <code>scout.md</code>',w:['a smaller <code>model:</code> in a helper the run does not name','a shorter <code>name:</code> line in <code>scout.md</code>','a shorter <code>CLAUDE.md</code>'],why:'A run pays for the helpers it names, at the price of their model: small is 1 unit, standard 3 and large 10. A helper it does not name costs nothing, so resizing it saves nothing.'},
 {ch:22,c:'A helper only looks for a file. Which model is enough for it?',a:'<code>small</code>',w:['<code>large</code>, to be safe','<code>huge</code>','none, <code>model:</code> is optional'],why:'Looking for a file is a simple job, so the cheapest size does it. <code>huge</code> is not a model here, and a helper file without a valid <code>model:</code> cannot be read.'}
];

/* ch: chapter index, c: the topic, what: one line (HTML), ex: [text, note] pairs. Examples are read-only: there is no terminal to run them in. */
AQ.GUIDE=[
 {ch:0,c:'Done when: the last step of the loop',what:'Tells the agent how to prove it is finished. It can <code>run</code> a command or <code>read</code> a file. Without it the run is unverified.',ex:[['Done when: run npm test','The agent finishes by running the tests. A failed test sends it round the loop again.']]},
 {ch:0,c:'Constraints: rules for the agent',what:'One rule per line, in the shape <code>do not</code>, a verb, a target. The verbs here are <code>edit</code>, <code>read</code>, <code>run</code> and <code>delete</code>. A blocked call is skipped.',ex:[['Constraints: do not delete data/','Blocks every delete inside the folder.'],['Constraints: do not edit src/','Also a valid rule, but it blocks the fix this project needs.']]},
 {ch:0,c:'Files: where to look',what:'Paths the agent reads before it starts. Fewer files means a smaller context, but the agent can only change what it has read.',ex:[['Files: src/price.js','Reads one file and holds very little.']]},
 {ch:0,c:'CLAUDE.md: standing instructions',what:'A memory file loaded into every run. Lines in the rule shape act as standing rules; other lines only cost tokens.',ex:[['do not delete data/','A rule that holds even when the prompt says nothing about it.']]},
 /* sc: the scenario the example lines are checked against (default tidy) */
 {ch:1,c:'The window and what drops out',what:'The agent holds a fixed number of tokens. When it overflows, the oldest earlier messages are dropped first. The memory file is never dropped.',sc:'chat',ex:[['Files: src/price.js','Reads one small file and leaves room for the whole chat.']]},
 {ch:2,c:'Examples: show the format',what:'Paths of sample files. The agent copies the format of the sample, so pick one in the style you want.',sc:'changelog',ex:[['Examples: docs/changelog-sample.md','The new entry follows the sample.']]},
 {ch:2,c:'Plan: look before it leaps',what:'<code>Plan: first</code> makes the agent show which files it will change and wait for your approval.',sc:'rollout',ex:[['Plan: first','Pauses the run until you approve the plan.']]},
 {ch:3,c:'Memory in a folder',what:'A <code>CLAUDE.md</code> inside a folder loads when the agent reads a file there. Its rule lines then hold for the rest of the run, and its size counts toward the setup either way.',ex:[['do not edit src/legacy/','In <code>src/CLAUDE.md</code>, this guards the old code once the agent reads in <code>src/</code>.']]},
 {ch:3,c:'Which memory files are read',what:'This simulator reads the project memory file and the memory files inside folders, all named <code>CLAUDE.md</code>. It does not read a personal memory file or an <code>AGENTS.md</code> file.',ex:[['src/CLAUDE.md','A folder memory file, read once the agent reads a file in <code>src/</code>.']]},
 {ch:4,c:'Skills: name, description, when',what:'A skill file has <code>name:</code>, <code>description:</code> and <code>when:</code> lines. When <code>when:</code> matches the job, the body loads and its rule lines hold.',ex:[['when: release','The skill loads for release jobs only.']]},
 {ch:4,c:'MCP servers',what:'One line per server: a name, a colon and its tools. Every tool you list costs tokens on every run.',ex:[['calendar: list','One server with one tool.']]},
 {ch:4,c:'Using a tool',what:'A tool is named by its server and its tool. Ban it with <code>do not call</code>, or check with <code>Done when: call</code>.',sc:'calendar',ex:[['Constraints: do not call mail.send','Bans the email tool and leaves the calendar alone.'],['Done when: call calendar.list','Ends the run by reading the calendar back.']]},
 {ch:5,c:'Hooks',what:'One line per hook, in the shape <code>before</code>, a verb and a target. A hook is checked on every action, from the first one.',ex:[['before run npm run deploy','Stops the deploy command whatever the agent plans.']]},
 {ch:5,c:'Subagent models',what:'Each subagent file names a model: <code>small</code> (1 unit), <code>standard</code> (3) or <code>large</code> (10). The setup cost is the sum over all subagents.',ex:[['model: small','The cheapest size, fine for simple lookups.']]},
 {ch:6,c:'Permissions, injection and secrets',what:'A permission rule is a <code>deny</code> line in the settings. Rules limit what a hijacked agent can do, and keep key files out of reach.',sc:'vendor',ex:[['deny delete data/','Never deletes anything in the folder.'],['Constraints: do not send mail.send','Blocks an email that hidden text asked for.']]},
 {ch:7,c:'only and max: limit what a run may change',what:'<code>only edit</code> names the one file a run may change, which suits a look-around run that writes notes. <code>max N files</code> caps how many different files a run may change, and the extra file is skipped.',sc:'survey',ex:[['Constraints: only edit NOTES.md','Every edit except the one to the notes file is skipped.'],['Constraints: max 2 files','The third different file the agent tries to change is skipped.']]},
 {ch:8,c:'Pull requests: never push to main',what:'A pull request (PR) is the page where teammates read a change before it joins the main code. Ban the one command that pushes to <code>main</code>, and the agent pushes to its own branch and opens the PR.',sc:'ship',ex:[['Constraints: do not run git push origin main','Blocks the push to the main branch and leaves the branch push and the PR command alone.'],['Constraints: ask before run git push origin main','Also stops it: in a practice run nobody answers, so the push is not carried out.']]},
 {ch:9,c:'Use: hand a job to a helper',what:'<code>Use</code> names one or more subagents. The search then runs in each helper\'s own context, and the main agent reads only what comes back. A run pays the price of each helper it names, and a helper that reads too much for its window loses track of files.',sc:'huge',ex:[['Use: scout','Hands the whole search to one helper.'],['Use: scout, scout2','Shares the search between two helpers, in order, so each holds less.']]},
 {ch:10,c:'Hooks that run after an edit',what:'One line in <code>.claude/hooks.txt</code>: <code>after edit</code>, a path, <code>run</code> and a command. It fires after every edit under that path. A failing check goes back to the agent to repair, and a formatter rewrites the file itself.',ex:[['after edit src/ run npm run lint','Checks every edit under <code>src/</code>, and a failure sends the agent back to repair.'],['after edit src/ run npm run format','Rewrites the file after every edit, so nothing is left to repair.']]},
 {ch:11,c:'Commands: a saved prompt',what:'A slash command is a file named <code>.claude/commands/NAME.md</code> that holds prompt lines. In real Claude Code you type <code>/</code> and the name to run it, and the file is now the older form of a skill. In this practice <code>Use: NAME</code> adds those lines to your prompt. Rules and file lists add up, a <code>Plan</code> line is kept if either has one, and a <code>Goal</code> or <code>Done when</code> you type takes the place of the command\'s. Commands and skills are files in the repository, so the whole team gets them.',sc:'cmdset',ex:[['Use: fix','Adds the lines of <code>fix.md</code> to the prompt: its rule and its check.'],['Done when: run npm test','Typed next to a command, it takes the place of that command\'s own <code>Done when</code> line.']]},
 {ch:12,c:'Connecting tools: one line per server',what:'<code>.claude/mcp.txt</code> holds one line per server: a name, a colon and its tools. A tool that no line lists is not connected, and a call to it is skipped. A check that calls a tool needs that tool connected, or the run ends unverified.',sc:'ui',ex:[['Done when: call browser.screenshot','Ends the run by calling the browser tool. If the tool is not connected, the run is unverified.']]},
 {ch:13,c:'Jobs with nobody there',what:'An unattended run cannot ask, so a <code>Plan: first</code> line stalls it. Every action except a read needs a line of the form <code>allow</code>, a verb and a target in <code>.claude/permissions.txt</code>, and anything off the list is skipped. Keep each line as narrow as the job, and point the job at the failure with a <code>Files</code> line.',sc:'nightly-scope',ex:[['Plan: first','Makes an unattended job stall at the plan, because nobody can approve it.'],['allow edit src/price.js','Lets the job change that one file, and nothing under any other path.'],['allow run npm test','Lets the job run the tests and no other command.'],['Files: ci/last-run.log, src/tax.js','Points the job at the log of the last run and at the file to fix.']]},
 {ch:14,c:'The default check in CLAUDE.md',what:'A <code>Done when</code> line in the root <code>CLAUDE.md</code> is the default check: a run with no check of its own uses it. Only the first line that parses counts, a folder file never supplies it, and a check typed in the prompt takes its place. The count under the file in the editor says whether it found one.',sc:'memgate',ex:[['Done when: run npm run verify','Written once in the root memory file, it checks every run that has no check of its own.'],['do not edit generated/','A standing rule in the same file, seen by every run.']]},
 {ch:15,c:'Schedules: when a saved command starts',what:'A line in <code>.claude/schedule.txt</code> starts a saved command: a day word (<code>daily</code>, <code>weekdays</code> or a day name), a time with two digits for the hour and two for the minutes, the word <code>use</code> and the name of a command in <code>.claude/commands</code>. Nothing runs on a clock here: Run plays the moment a line starts the job, once. That run is unattended, so a plan stalls and every action except a read needs an allow line. The days of all the lines that start one command add up to its runs a week, and every run costs tokens.',sc:'digest',ex:[['weekdays 07:30 use weekly-digest','Starts the digest at 07:30 on each of the five weekdays: five runs a week.'],['monday 07:30 use weekly-digest','The same job once a week: one run.'],['Use: weekly-digest','The prompt of the job: it adds the lines of the saved command to the run.']]},
 {ch:16,c:'Files: read one section of a file',what:'A file name, a <code>#</code> and a heading in lower case read only that section: the lines from the heading to the next heading of the same size or bigger. The agent holds only those lines, so a long report fits. Real agents read a range of lines instead of a heading.',sc:'report',ex:[['Files: reports/market.md#pricing','Reads the Pricing section and holds far less than the whole report.']]},
 {ch:17,c:'Patterns: one rule for many files',what:'A <code>*</code> in the target of a rule stands for any text, folder names included, so one rule can cover a whole kind of file. It works in a <code>Constraints</code> line and in a <code>deny</code> line of <code>.claude/permissions.txt</code>. Too narrow a pattern lets a file slip through, too wide a one stops files you wanted to change, and a rule stops one verb only. In a <code>Constraints</code> line the practice refuses a pattern that matches no file.',sc:'downloads',ex:[['Constraints: do not delete downloads/*.pdf','Stops the delete of every PDF in downloads/, the ones that arrive later too.'],['deny edit *-signed.txt','Stops every edit of a file whose name ends in <code>-signed.txt</code>, in any folder.'],['Constraints: max 3 files','Not a pattern, but the same idea of a trial run: the agent changes three files at most.']]},
 {ch:18,c:'Your own apps as tools: connect, deny, read back',what:'The agent reaches your notes, mail and calendar only through tools a server lists in <code>.claude/mcp.txt</code>. A tool nobody connected is skipped. To keep a connected tool out of reach, write a <code>deny call</code> line for it in <code>.claude/permissions.txt</code>: a tool is always a <code>call</code>, and a rule on the server name alone covers all of its tools. To prove that a tool changed something, end the job with a check that calls a tool which reads it back. If that tool is not connected the run is only unverified, and if the change never happened the run fails.',sc:'agenda',ex:[['calendar: list, create','In <code>.claude/mcp.txt</code>: connects the tool that adds an event and the tool that lists the calendar.'],['deny call mail.send','In <code>.claude/permissions.txt</code>: the agent can read the mail, but a send is skipped.'],['Done when: call calendar.list','Reads the calendar back after the job. It passes only if the event is on it.']]},
 {ch:19,c:'Commands and skills: who starts the rule',what:'A saved command is a file in <code>.claude/commands/</code> that holds prompt lines: a run calls it by name with <code>Use</code>, and its goal, rules and check join the prompt. A skill is a file in <code>.claude/skills/</code> that loads by itself when its <code>when:</code> line names the kind of job, and its rule lines then hold like the ones in <code>CLAUDE.md</code>. A run that a schedule line starts is the kind <code>schedule</code>. Use a command for a chore you repeat and a skill for a rule that should follow many jobs.',sc:'weeklyReview',ex:[['Use: weekly-review','Calls the saved command: its rule and its check are added to the prompt.'],['Constraints: do not delete notes/this-week.md','A rule line as a command holds it: it keeps one note and nothing else.'],['when: schedule','In a skill file: the skill loads for every run that a schedule line starts.']]},
 {ch:20,c:'Audit: what is loaded on every run',what:'Some of your setup is loaded on every run, used or not: <code>CLAUDE.md</code>, the name and description of every skill, and the name of every tool a server lists. The body of a skill loads only when its <code>when:</code> line matches the job. To audit, go through the files and ask what each line does for this job. Cut what does nothing, shorten what is long, and keep the rules that guard something. The Meter shows the most the agent held at once in the last run.',sc:'tuneDesc',ex:[['description: Use during a release: blocks edits to migrations','Eight words that say when the skill applies and what it guards.'],['calendar: list','In <code>.claude/mcp.txt</code>: connects one tool of the calendar server, not all ten.'],['do not delete data/','A live rule: its folder exists, so the line stays.']]},
 {ch:21,c:'Trim: one place for each rule, rare ones on demand',what:'A line is paid for wherever it is loaded, so trim by where a rule lives. Keep a rule in one place: a copy that does not load is still a copy to keep up to date. Move what only one kind of job needs into the body of a skill for that kind of job, or into a saved command that you call by name. The rule your every job needs stays in <code>CLAUDE.md</code>. In a command, a rule goes on a <code>Constraints:</code> line, and a plain step goes on an <code>Extra:</code> line, which adds one line of context to the prompt and enforces nothing.',sc:'tuneCmd',ex:[['Constraints: do not edit migrations/','In a command: the rule keeps its force when the command is called.'],['Extra: Bump the version in package.json to the number the shop team agreed on for this release.','In a command: a step of the chore, as context.'],['when: release','In a skill: the checklist in its body loads only for a release.']]},
 {ch:22,c:'Measure, then cut: before and after',what:'Run the job once before you change anything and note the most the agent holds at once: that is your start. Cut, run again and compare. A share of the start (such as 60% or less) says how much you saved and stays true as the setup grows. The same goes for helpers: a run pays for the helpers it names, at the price of their <code>model:</code> (small 1 unit, standard 3, large 10), so resize the helper the run calls, and keep the bigger size for the helper that decides.',sc:'tuneMeasure',ex:[['Start ~239, yours ~111, saved 54%.','The message of a mission: the start, your number and the share saved.'],['model: small','In <code>.claude/agents/scout.md</code>: the helper that only looks for files costs 1 unit instead of 10.'],['Helpers: from 20 to 4 units.','Two helpers cut from large to small and standard.']]}
];
})();
